static guint16
read_be16 (const guint8 *data)
{
  return ((guint16) data[0] << 8) | data[1];
}

static guint32
read_le32 (const guint8 *data)
{
  return ((guint32) data[0]) |
         ((guint32) data[1] << 8) |
         ((guint32) data[2] << 16) |
         ((guint32) data[3] << 24);
}

static gboolean
validity_rom_info_is_supported_capture_family (const ValidityRomInfo *rom_info)
{
  return rom_info != NULL &&
         rom_info->valid &&
         rom_info->build == 154 &&
         rom_info->major == 6 &&
         rom_info->minor == 20 &&
         rom_info->product == 0x33 &&
         rom_info->u1 == 1;
}

gboolean
validity_parse_rom_info_response (ValidityRomInfo *rom_info,
                                  const guint8    *plain,
                                  gsize            plain_len,
                                  GError         **error)
{
  const guint8 *body;

  g_return_val_if_fail (rom_info != NULL, FALSE);
  g_return_val_if_fail (plain != NULL, FALSE);

  if (plain_len < 18)
    {
      g_set_error (error, G_IO_ERROR, G_IO_ERROR_INVALID_DATA,
                   "RomInfo response too short: %zu B", plain_len);
      return FALSE;
    }

  if (read_be16 (plain) != VALIDITY_STATUS_OK)
    {
      g_set_error (error, G_IO_ERROR, G_IO_ERROR_INVALID_DATA,
                   "RomInfo response status 0x%04x", read_be16 (plain));
      return FALSE;
    }

  memset (rom_info, 0, sizeof (*rom_info));
  body = plain + 2;

  rom_info->timestamp = read_le32 (body + 0x00);
  rom_info->build     = read_le32 (body + 0x04);
  rom_info->major     = body[0x08];
  rom_info->minor     = body[0x09];
  rom_info->product   = body[0x0b];
  rom_info->u1        = body[0x0f];
  rom_info->raw_len   = MIN (plain_len - 2, (gsize) VALIDITY_ROM_INFO_RAW_MAX);
  memcpy (rom_info->raw, body, rom_info->raw_len);
  rom_info->valid = TRUE;

  return TRUE;
}

guint8 *
validity_capture_build (const ValidityRomInfo *rom_info,
                        ValidityCaptureMode    mode,
                        gsize                 *out_len,
                        GError               **error)
{
  guint8 *cmd;

  g_return_val_if_fail (out_len != NULL, NULL);

  if (mode != VALIDITY_CAPTURE_MODE_IDENTIFY &&
      mode != VALIDITY_CAPTURE_MODE_ENROLL)
    {
      g_set_error (error, G_IO_ERROR, G_IO_ERROR_INVALID_ARGUMENT,
                   "unsupported capture mode 0x%02x", (guint) mode);
      return NULL;
    }

  if (rom_info != NULL && rom_info->valid &&
      !validity_rom_info_is_supported_capture_family (rom_info))
    {
      g_set_error (error, G_IO_ERROR, G_IO_ERROR_NOT_SUPPORTED,
                   "unsupported 0088 ROM family for constructed capture program: "
                   "build=%u major=%u minor=%u product=0x%02x u1=%u",
                   rom_info->build, rom_info->major, rom_info->minor,
                   rom_info->product, rom_info->u1);
      return NULL;
    }

  cmd = g_memdup2 (validity_capture_identify_template,
                   sizeof (validity_capture_identify_template));
  cmd[VALIDITY_CAPTURE_MODE_OFFSET] = (guint8) mode;
  *out_len = sizeof (validity_capture_identify_template);

  return cmd;
}
